package com.zuoqirun.lyricscompanion;

import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.*;

public class FoliaOriginalSonnetTest {
    @Test public void shotFramesMatchPinnedUpstreamAbsoluteTimeSnapshots() {
        // Generated by tools/folia-original/sonnet-motion-oracle.mjs at upstream 9279251.
        double[][] expected = {
                {-0.011933333333, 0.006866666667, 1.011733333333, -0.001466666667},
                {-0.003266666667, 0.005306666667, 1.036266666667, -0.002746666667},
                {-0.012857562006, -0.023018933188, 1.004033169641, -0.003411902778},
                {-0.054119027785, 0.017857562006, 1.006470243054, 0.002705951389},
                {0.005533333333, 0.0388, 1.0144, -0.00192},
                {-0.002924488096, 0.001949658731, 0.999453658234, -0.000365561012},
                {-0.006874146826, 0.004546341766, 1.010588097222, -0.000865561012}
        };
        float[] actual = new float[4];
        for (int i = 0; i < FoliaOriginalSonnetProgram.KINDS.length; i++) {
            FoliaOriginalSonnetMotion.frame(FoliaOriginalSonnetProgram.KINDS[i], 0.43, actual);
            for (int axis = 0; axis < 4; axis++) assertEquals(expected[i][axis], actual[axis], 0.000002);
        }
    }

    @Test public void focusWeightsRemainStableInSilentGapsAndDistantSeeks() {
        float[] weights = new float[3];
        long[] starts = {1000, 2000, 4000}, ends = {1200, 2300, 4500};
        FoliaOriginalSonnetMotion.weights(starts, ends, 1800, weights);
        assertEquals(0.213136421564, weights[0], 0.000001);
        assertEquals(0.786863575996, weights[1], 0.000001);
        assertEquals(2.4393429244227864e-9, weights[2], 0.00000000001);
        FoliaOriginalSonnetMotion.weights(starts, ends, 100_000_000, weights);
        assertEquals(1, weights[2], 0.000001);
        assertEquals(0, weights[0], 0);
    }

    @Test public void smoothingPreservesIntentionalCompositionJumpsAndContinuousPan() {
        float[] center = new float[2], scratch = new float[2], result = new float[2];
        FoliaOriginalSonnetMotion.smoothFocus(1000, 0, 3000,
                (time, out) -> { out[0] = time < 1000 ? -500 : 500; out[1] = 0; },
                center, scratch, result);
        assertEquals(500, result[0], 0);
        FoliaOriginalSonnetMotion.smoothFocus(1000, 0, 3000,
                (time, out) -> { out[0] = (float) time * 0.2f; out[1] = (float) time * -0.1f; },
                center, scratch, result);
        assertEquals(200, result[0], 0.0001);
        assertEquals(-100, result[1], 0.0001);
    }

    @Test public void programKeepsTimedWordsAndAllSevenShotFamiliesSeekSafe() {
        List<LrcTimeline.Line> lines = new ArrayList<>();
        for (int i = 0; i < 24; i++) lines.add(new LrcTimeline.Line(i * 2000, 1200, "lyric " + i + "!"));
        FoliaOriginalSonnetProgram first = new FoliaOriginalSonnetProgram(lines, "song-a");
        FoliaOriginalSonnetProgram rebuilt = new FoliaOriginalSonnetProgram(lines, "song-a");
        assertTrue(first.paragraphs.size() > 1);
        assertEquals(first.shots.size(), rebuilt.shots.size());
        for (int i = 0; i < first.shots.size(); i++) {
            FoliaOriginalSonnetProgram.Shot shot = first.shots.get(i);
            assertTrue(shot.lines.size() <= 4);
            assertEquals(shot.kind, rebuilt.shots.get(i).kind);
            assertEquals(shot.id, first.shotAt(shot.start).id);
            assertEquals(shot.zoom, rebuilt.shots.get(i).zoom, 0);
        }
        LrcTimeline.Line timed = new LrcTimeline.Line(1000, 4000, "time, time.", "",
                Arrays.asList(new LrcTimeline.Word(1000, 800, "time"), new LrcTimeline.Word(3000, 900, "time")));
        List<FoliaOriginalSonnetProgram.Segment> segments = FoliaOriginalSonnetProgram.segments(timed, 6000, 0);
        StringBuilder text = new StringBuilder();
        List<FoliaOriginalSonnetProgram.Segment> words = new ArrayList<>();
        for (FoliaOriginalSonnetProgram.Segment segment : segments) {
            text.append(segment.text);
            if (segment.word) words.add(segment);
        }
        assertEquals(timed.text, text.toString());
        assertEquals(2, words.size());
        assertEquals(1000, words.get(0).start());
        assertEquals(3000, words.get(1).start());
    }

    @Test public void posterRowsMatchOriginalZoneFloatAndJustification() {
        List<FoliaOriginalSonnetLayout.Box> boxes = posterBoxes();
        FoliaOriginalSonnetLayout.poster(boxes, 800, 480, 32, 42);
        float[][] expected = {{-306, -83.4f, 60, 24}, {-246, -8, 180, 90}, {-105, -41, 70, 24},
                {-286, 75.4f, 100, 40}, {-175, 67.4f, 90, 24}};
        assertPoster(expected, boxes);
        for (FoliaOriginalSonnetLayout.Box box : boxes) assertFalse(box.vertical);
    }

    @Test public void posterColumnsMatchOriginalVerticalMeasurementAndZoneFit() {
        List<FoliaOriginalSonnetLayout.Box> boxes = posterBoxes();
        FoliaOriginalSonnetLayout.poster(boxes, 800, 480, 32, 43);
        float[][] expected = {{103.4f, -180, 60, 24}, {25.24f, -72.96f, 59.52f, 238.08f},
                {20, 74.08f, 70, 24}, {-83.4f, -172, 100, 40}, {-78.4f, -124, 90, 24}};
        assertPoster(expected, boxes);
        assertTrue(boxes.get(1).vertical);
        assertEquals(3.472f * 32, boxes.get(1).size, 0.001);
    }

    private static List<FoliaOriginalSonnetLayout.Box> posterBoxes() {
        List<FoliaOriginalSonnetLayout.Box> boxes = new ArrayList<>();
        float[][] source = {{0, 1, 60, 24}, {2, 4, 180, 90}, {0, 1, 70, 24}, {1, 2, 100, 40}, {0, 1, 90, 24}};
        for (float[] value : source) {
            FoliaOriginalSonnetLayout.Box box = new FoliaOriginalSonnetLayout.Box();
            box.role = (int) value[0]; box.size = value[1] * 32;
            box.width = value[2]; box.height = value[3];
            boxes.add(box);
        }
        boxes.get(1).verticalWidth = 60;
        boxes.get(1).verticalHeight = 240;
        boxes.get(1).verticalSize = 3.5f * 32;
        return boxes;
    }

    private static void assertPoster(float[][] expected, List<FoliaOriginalSonnetLayout.Box> boxes) {
        for (int i = 0; i < expected.length; i++) {
            FoliaOriginalSonnetLayout.Box box = boxes.get(i);
            assertEquals(expected[i][0], box.x, 0.001);
            assertEquals(expected[i][1], box.y, 0.001);
            assertEquals(expected[i][2], box.width, 0.001);
            assertEquals(expected[i][3], box.height, 0.001);
        }
    }
}
